import json, random, subprocess, copy
from fractions import Fraction

SUB=['python3','/workspace/submission/main.py']

def ref(d):
    cfg=d['config']; m=d['model']; C=m['classes']; W=cfg['window']; K=m['kernel']; E=m['embedding_dim']
    cs=[]
    for x in d['connections']:
        cs.append(dict(x, packets=0,votes=[0]*C))
    cmap={x['id']:x for x in cs}
    slots=[dict(cid=None,gen=0,win=[],cache=None,lastid=-1,anchor=0,backlog=0,lasttime=0) for _ in range(cfg['slots'])]
    avail=[0]*cfg['lanes']; jobs=[]; pending=set(); outpack=[]
    credit=cfg['initial_tokens']*cfg['rate_den']; lastref=0
    def complete(jid):
        j=jobs[jid]; s=slots[j['slot']]
        if s['cid'] is None or s['cid']!=j['connection'] or s['gen']!=j['generation']:
            j['status']='stale'
        elif jid<=s['lastid']:
            j['status']='superseded'
        else:
            j['status']='applied';s['cache']=j['prediction'];s['lastid']=jid
    def cnn(win):
        x=[]
        for a,b in win:
            x.append(m['length_embedding'][a]+m['gap_embedding'][b])
        pool=[]
        for f in range(len(m['conv_weights'])):
            vals=[]
            for j in range(W-K+1):
                z=m['conv_bias'][f]
                for k in range(K):
                    for dd in range(2*E):
                        z+=m['conv_weights'][f][k][dd]*x[j+k][dd]
                sh=m['conv_shift'][f]
                if sh:
                    if z<0: z=-(((-z)+(1<<(sh-1)))//(1<<sh))
                    else: z=(z+(1<<(sh-1)))//(1<<sh)
                vals.append(max(0,min(127,z)))
            pool.append(max(vals))
        logits=[m['dense_bias'][c]+sum(m['dense_weights'][c][f]*pool[f] for f in range(len(pool))) for c in range(C)]
        pred=max(range(C),key=lambda c:(logits[c],-c))
        return logits,pred
    for ix,p in enumerate(d['packets']):
        t=p['time']
        done=sorted((jobs[j]['done'],j) for j in pending if jobs[j]['done']<=t)
        for _,j in done:
            complete(j);pending.remove(j)
        credit=min(cfg['bucket_capacity']*cfg['rate_den'],credit+(t-lastref)*cfg['rate_num']);lastref=t
        co=cmap[p['connection']];s=slots[co['slot']]
        if s['cid'] is None or s['cid']!=co['id'] or t-s['lasttime']>=cfg['idle_timeout']:
            s.update(cid=co['id'],gen=s['gen']+1,win=[],cache=None,lastid=-1,anchor=t,backlog=0)
            gap=0
        else:gap=t-s['lasttime']
        s['lasttime']=t
        q=[min(15,p['length']//cfg['len_quantum']),min(15,gap//cfg['gap_quantum'])]
        s['win']=(s['win']+[q])[-W:];s['backlog']+=1
        fw=s['cache'] if s['cache'] is not None else cfg['fallback']
        co['packets']+=1;co['votes'][fw]+=1
        jid=None
        if len(s['win'])<W:dec='warmup'
        else:
            ti=t-s['anchor'];ci=s['backlog']
            tb=max(i for i,e in enumerate(cfg['time_edges']) if e<=ti)
            cb=max(i for i,e in enumerate(cfg['count_edges']) if e<=ci)
            prob=cfg['probability'][tb][cb]
            if p['draw']>=prob:dec='probability'
            elif credit<cfg['rate_den']:dec='tokens'
            elif len(pending)>=cfg['pending_capacity']:dec='queue'
            else:
                dec='sent';credit-=cfg['rate_den'];jid=len(jobs)
                win=copy.deepcopy(s['win']);logits,pred=cnn(win)
                lane=min(range(cfg['lanes']),key=lambda l:(avail[l],l))
                start=max(t,avail[lane]);done_at=start+cfg['service'][pred];avail[lane]=done_at
                jobs.append(dict(id=jid,packet=ix,connection=co['id'],slot=co['slot'],generation=s['gen'],lane=lane,start=start,done=done_at,window=win,logits=logits,prediction=pred,status=None))
                pending.add(jid);s['anchor']=t;s['backlog']=0
        outpack.append(dict(index=ix,connection=co['id'],generation=s['gen'],forward=fw,decision=dec,credit=credit,job=jid))
    for _,j in sorted((jobs[j]['done'],j) for j in pending):complete(j)
    cout=[]
    for co in cs:
        pred=max(range(C),key=lambda c:(co['votes'][c],-c)) if co['packets'] else None
        cout.append({k:co[k] for k in ('id','split','label','packets','votes')}|{'prediction':pred})
    reports={}
    for split in ('dev','eval'):
        mat=[[0]*C for _ in range(C)];n=0
        for co in cout:
            if co['split']==split and co['packets']:
                n+=1;mat[co['label']][co['prediction']]+=1
        f=Fraction()
        for c in range(C):
            tp=mat[c][c];fp=sum(row[c] for row in mat)-tp;fn=sum(mat[c])-tp
            den=2*tp+fp+fn
            if den:f+=Fraction(2*tp,den)
        f/=C
        reports[split]=dict(connections=n,confusion=mat,macro_f1=[f.numerator,f.denominator])
    return dict(packets=outpack,jobs=jobs,connections=cout,reports=reports)

def gen(r):
    C=r.randint(2,5);E=r.randint(1,4);W=r.randint(1,6);K=r.randint(1,min(5,W));F=r.randint(1,4);S=r.randint(1,3)
    cfg=dict(slots=S,window=W,idle_timeout=r.randint(1,10),len_quantum=r.randint(1,5),gap_quantum=r.randint(1,5),rate_num=r.randint(1,5),rate_den=r.randint(1,5),bucket_capacity=r.randint(1,5),initial_tokens=0,pending_capacity=r.randint(1,4),lanes=r.randint(1,3),service=[r.randint(1,10) for _ in range(C)],fallback=r.randrange(C),time_edges=[0,2,5],count_edges=[0,1,3],probability=[[r.randrange(65537) for _ in range(3)] for __ in range(3)])
    cfg['initial_tokens']=r.randint(0,cfg['bucket_capacity'])
    def vec(n):return [r.randint(-128,127) for _ in range(n)]
    m=dict(classes=C,embedding_dim=E,length_embedding=[vec(E) for _ in range(16)],gap_embedding=[vec(E) for _ in range(16)],kernel=K,conv_weights=[[[r.randint(-128,127) for _ in range(2*E)] for _ in range(K)] for __ in range(F)],conv_bias=[r.randint(-2**31,2**31-1) for _ in range(F)],conv_shift=[r.randint(0,16) for _ in range(F)],dense_weights=[vec(F) for _ in range(C)],dense_bias=[r.randint(-2**31,2**31-1) for _ in range(C)])
    n=r.randint(0,6)
    cons=[dict(id=f'c{i}',slot=r.randrange(S),label=r.randrange(C),split=r.choice(['dev','eval'])) for i in range(n)]
    packs=[];t=0
    for i in range(r.randint(0,35) if n else 0):
        t+=r.randint(0,8)
        packs.append(dict(time=t,connection=r.choice(cons)['id'],length=r.randrange(65536),draw=r.randrange(65536)))
    return dict(version=1,config=cfg,model=m,connections=cons,packets=packs)

